    seeds=[(r,c,int(A[r][c])) for r in range(H) for c in range(W) if A[r][c]!=0]
    F={}
    for r in range(H):
        for c in range(W):
            vals=[]
            for sr,sc,col in seeds:
                d=max(abs(r-sr),abs(c-sc)); m=abs(r-sr)+abs(c-sc)
                vals.append((d,m,d%2,m%2))
            # actual output
            y=int(A[r][c]) if A[r][c]!=0 else (int(O[r][c]) if O is not None else None)
            F[(r,c)]=(vals,y)
    return A,seeds,F
