# Candidate: choose nearest seed by CHEB among those with even cheb dist; tie by max color; else 0
def g1(A,r,c):
    cand=[]
    for i,(sr,sc,col) in enumerate(seeds_of(A)):
        d=max(abs(r-sr),abs(c-sc))
        if d%2==0: cand.append((d,-col,i))
    if not cand: return 0
    i=min(cand)[2]
    col=seeds_of(A)[i][2]; 
    # tie between two seeds with equal minimal d: max color
    dd=min(d for _,_,_ in cand)
    winners=[s for s,(d,_,_) in enumerate(cand) if d==dd]
    col=max(A[np.where(np.array(seeds_of(A))[i][:2])==[sr,sc]]) if False else seeds_of(A)[min(( -x[1] ,x[2]) for x in [(d,-x[1],i) for d,x in []])[0]]
    return col
seeds_all={}
def seeds_of(A):
    global seeds_all
    if A not in seeds_all: seeds_all[A]=[(r,c,int(A[r][c])) for r in range(A.shape[0]) for c in range(A.shape[1]) if A[r][c]!=0]
    return seeds_all[A]
def h(A,r,c):
    ca=[]
    for i,(sr,sc,col) in enumerate(seeds_of(A)):
        d=max(abs(r-sr),abs(c-sc))
        if d%2==0: ca.append((d,-col,i))
    if not ca: return 0
    dd=min(d for d,_,_ in ca)
    winners=sorted(set([(-ca[i][1],ca[i][2]) for i,d,ii in enumerate(ca) if d==dd]))
    ii=min(x[1] for x in winners)[0]
    return seeds_of(A)[ii][2]
print('g1 acc:',count_acc(lambda A,r,c:h(A,r,c)))

